  SELECT d.id, 'ea905d58-f0eb-47a2-a290-8b9cee5a0974', 'artist', '3dd83e6b-2058-4d04-ac68-38e11d9348a9' FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
