UPDATE artists SET bio_en = 'Lady Laura, known as “La Morena del Swing” —born Laura Isabel Polanco Jaime in Villa Altagracia— is a Dominican bachata singer who rose to popularity through social media in 2019 and has since shared stages with several of the genre’s leading names.

**From the church choir to her first recording**

She discovered her voice as a child in the choir of her community’s church. In 2018 she placed fourth, and won the audience prize, at a major bachata festival, and that result led her to start a music project and record «La mejor versión de mí», the song popularized by Natti Natasha, in a professional studio. Her popularity took off in early 2019 through social media; once she began performing for hire, her followers gave her the name “La Morena del Swing” on their own, so the stage name came from her audience rather than from a label. That year she also recorded «Te pareces tanto a él», a song by Myriam Hernández.

**Covers and first singles**

Her repertoire includes «Pude», «Confieso» and, from October 2023, a bachata version of Karol G’s «Mi ex tenía razón», with a video directed by «Controles Films» that was well received on radio. That month she was announced for the «Festival ADN Bachata» in Puerto Plata, scheduled for 16 to 20 November 2023.

**Sharing stages with the genre’s names**

On 21 March 2024 she sang at the unveiling of the stars of Luis Segura, José Manuel Calderón and Leonardo Paniagua on the «Bulevar de las Estrellas» on Avenida Winston Churchill in Santo Domingo, and shortly before had joined Prince Royce on stage in Santiago de los Caballeros for «Me enRD», in mixes by DJ Adoni. According to a press release published by Diario Libre, Antony Santos, Joe Veras, El Chaval de la Bachata, Romeo Santos and Prince Royce have praised her talent; her official biography adds that she has also shared stages with Antony Santos and Frank Reyes.

**Legacy**

In August 2025 she released «Quedarme con él», written by Carina Quisquella Martín Muñoz and distributed by «La Oreja Media Group», with a video shot in her hometown of Villa Altagracia. A month later came «Me frisó», with Crazy Design, which has passed one million views on YouTube. She has also announced a further collaboration with a Dominican urban artist.' WHERE slug = 'lady-laura';

INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lady Laura, conocida como “La Morena del Swing” —nacida Laura Isabel Polanco Jaime en Villa Altagracia— es cantante dominicana de bachata que ganó popularidad a través de las redes sociales en 2019 y desde entonces ha compartido escenario con varios de los nombres principales del género."}]},{"type":"paragraph","content":[{"type":"text","text":"Del coro de la iglesia a su primera grabación","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Descubrió su voz de niña en el coro de la iglesia de su comunidad. En 2018 quedó en cuarto lugar, y ganó el premio del público, en un importante festival de bachata, y ese resultado la llevó a iniciar su proyecto musical y a grabar en un estudio profesional «La mejor versión de mí», tema popularizado por Natti Natasha. Su popularidad despegó a principios de 2019 gracias a las redes sociales; cuando empezó a presentarse por contratación, sus seguidores le pusieron por cuenta propia el nombre “La Morena del Swing”, de modo que el nombre artístico salió de su público y no de un sello. Ese año grabó también «Te pareces tanto a él», tema de Myriam Hernández."}]},{"type":"paragraph","content":[{"type":"text","text":"Versiones y primeros sencillos","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Su repertorio incluye «Pude», «Confieso» y, desde octubre de 2023, una versión en bachata de «Mi ex tenía razón», de Karol G, con un video dirigido por «Controles Films» que tuvo buena acogida en la radio. Ese mes se anunció su participación en el «Festival ADN Bachata» de Puerto Plata, previsto del 16 al 20 de noviembre de 2023."}]},{"type":"paragraph","content":[{"type":"text","text":"Escenarios compartidos con los nombres del género","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"El 21 de marzo de 2024 cantó en la develación de las estrellas de "},{"type":"artistReference","attrs":{"occurrenceId":"7cf480d8-46fe-417a-aee5-db4906b6ec0c","artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"occurrenceId":"93aa9fe6-ccb4-4b0b-ad16-71513ca529b9","artistId":"27c82e93-8c8f-4466-86ab-e1afba1e5487","displayText":"José Manuel Calderón"}},{"type":"text","text":" y "},{"type":"artistReference","attrs":{"occurrenceId":"080b28e0-afa0-4ebe-8fa2-bd051dc38a73","artistId":"31915623-3206-4052-b13a-2170226671b9","displayText":"Leonardo Paniagua"}},{"type":"text","text":" en el «Bulevar de las Estrellas» de la avenida Winston Churchill, en Santo Domingo, y poco antes había acompañado a "},{"type":"artistReference","attrs":{"occurrenceId":"460c227a-d2d2-42b1-888c-4226194a303a","artistId":"9c02d1a1-952e-4855-9b60-c0266236378d","displayText":"Prince Royce"}},{"type":"text","text":" en tarima en Santiago de los Caballeros con «Me enRD», en mezclas de "},{"type":"artistReference","attrs":{"occurrenceId":"0ab3e4e0-8d5c-4821-a4cd-8d8a048774ee","artistId":"8243655e-17a7-4dea-98ee-1c16674c38cd","displayText":"DJ Adoni"}},{"type":"text","text":". Según una nota de prensa publicada por Diario Libre, "},{"type":"artistReference","attrs":{"occurrenceId":"8936b620-5f19-4e80-b605-7c9125f860ea","artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"occurrenceId":"25bdf5dd-2cb7-40f7-a252-84de8fd16603","artistId":"aec32df5-cc5a-43c2-ac33-02bc8caa1cf5","displayText":"Joe Veras"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"occurrenceId":"5b037e9d-6531-426b-bd40-e79d555c6c34","artistId":"8be8c38c-e6a5-4e0d-83d1-8c8d20813ce6","displayText":"El Chaval de la Bachata"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"occurrenceId":"7c84313b-420a-42b6-b6d4-785dd7000b2f","artistId":"8f1d2a44-3c6e-4b17-9a58-7d0e5c9b21f3","displayText":"Romeo Santos"}},{"type":"text","text":" y "},{"type":"artistReference","attrs":{"occurrenceId":"e221c374-4230-4648-855c-29364b16bc19","artistId":"9c02d1a1-952e-4855-9b60-c0266236378d","displayText":"Prince Royce"}},{"type":"text","text":" han elogiado su talento; su biografía oficial añade que también ha compartido escenario con "},{"type":"artistReference","attrs":{"occurrenceId":"dbd74fa9-5d51-40cf-8c6b-1c0b62a95228","artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos"}},{"type":"text","text":" y "},{"type":"artistReference","attrs":{"occurrenceId":"37b4852b-ba8d-4dc9-b8a3-fc4e1683b54e","artistId":"3dd83e6b-2058-4d04-ac68-38e11d9348a9","displayText":"Frank Reyes"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Legado","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"En agosto de 2025 publicó «Quedarme con él», con letra de Carina Quisquella Martín Muñoz y distribución de «La Oreja Media Group», con un video rodado en su Villa Altagracia natal. Un mes después llegó «Me frisó», con Crazy Design, que ha superado el millón de vistas en YouTube. También ha anunciado una nueva colaboración con un artista urbano dominicano."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'lady-laura';
